    payload = {
        "旧会话": old,
        "旧地址": old_address,
        "旧期限": old_deadline,
        "旧租期": old_lease,
        "新会话": sid,
        "状态": _STATE_ONLINE,
        "时刻": now_ms,
        "期限": deadline,
        "池": pool_id,
