auth = Authenticator(3, 1000)
for u in ("alice", "bob"):
    auth.add(u, "pw")
s = Sessions(auth, 4, 4, 100000, pool=("10.0.0.0/30", (), ()), lease_ms=100000)

# fault inject/recover JSON
print(s.fault("f1", "注入", 500, 10), end="")
print(s.fault("f2", "恢复", None, 10), end="")
s.fault("f1", "注入", 500, 10)

# first probe t=10: n 0->1, r=110
try:
    s.do("d1", "建立", "s1", ("alice", "pw"), 10)
except BackendError as e:
    print("t10:", e.args, s._backoff)
# same retry window t=50: n unchanged, r=110
try:
    s.do("d2", "建立", "s2", ("alice", "pw"), 50)
except BackendError as e:
    print("t50:", e.args, s._backoff)
# t=110: n 1->2, r=310
try:
    s.do("d3", "建立", "s3", ("alice", "pw"), 110)
except BackendError as e:
    print("t110:", e.args, s._backoff)
# t=510: both until(510) and r(310) arrived -> auth proceeds
out = s.do("d4", "建立", "s4", ("alice", "pw"), 510)
print("t510 ok:", json.loads(out)["状态"], "backoff:", s._backoff, "faults:", s._faults)

# bob healthy: works
print("bob:", json.loads(s.do("d5", "建立", "s5", ("bob", "pw"), 510))["状态"])

# replay cached BackendError same args, diff key params
try:
    s.do("d1", "建立", "s1", ("alice", "pw"), 10)
except BackendError as e:
    print("replay d1:", e.args)
try:
    s.do("d1", "建立", "s1", ("alice", "pw"), 11)
except ValueError as e:
    print("diff params:", e)

# fault param errors
for args in [("g1", True, 1, 0), ("g2", 1, 1, 0), ("g3", "注入", 0, 0),
             ("g4", "注入", True, 0), ("g5", "注入", 1, -1), ("g6", "注入", None, 0),
             ("g7", "恢复", 1, 0)]:
    try:
        s.fault(*args)
        print("NO ERROR", args)
    except (TypeError, ValueError) as e:
        print(type(e).__name__, args[0], str(e)[:40])
# replay of param error same type
try:
    s.fault("g3", "注入", 0, 0)
except ValueError:
    print("g3 replay ValueError ok")
try:
    s.fault("g3", "注入", 1, 0)
except ValueError:
    print("g3 diffparams ValueError ok")
